cd /tmp/probe_table && cat > move1.lua <<'EOF'
local function T(t,n) local s={} for i=1,(n or #t) do s[i]=tostring(t[i]) end return "{"..table.concat(s,",").."}" end
local function p(...) print(...) end
-- basic
local a = {1,2,3,4,5}
local r = table.move(a,1,3,3)
p("fwd overlap dst>src", T(a,7), rawequal(r,a))
local b = {1,2,3,4,5}
table.move(b,3,5,1); p("bwd overlap dst<src", T(b,5))
local c = {1,2,3,4,5}
table.move(c,1,5,1); p("identity", T(c,5))
local d = {1,2,3,4,5}
table.move(d,2,4,2); p("same pos", T(d,5))
-- cross table
local s1 = {1,2,3}
local d1 = {"a","b","c","d","e"}
local rr = table.move(s1,1,3,2,d1)
p("cross", T(d1,6), rawequal(rr,d1), rawequal(rr,s1))
-- e>f  (no move)
local z = {1,2,3}
local zr = table.move(z, 3, 1, 1); p("e>f noop", T(z,3), rawequal(zr,z))
local z2 = {1,2,3}
table.move(z2, 2, 1, 5); p("e>f noop2", T(z2,5))
-- negative/zero indices
local n = {}
n[-1]="m1"; n[0]="z"; n[1]="one"
table.move(n, -1, 1, 1)
p("neg src", tostring(n[-1]),tostring(n[0]),tostring(n[1]),tostring(n[2]),tostring(n[3]))
local n2 = {1,2,3}
table.move(n2, 1, 3, -1)
p("neg dst", tostring(n2[-1]),tostring(n2[0]),tostring(n2[1]),tostring(n2[2]),tostring(n2[3]))
-- return value with 5 args
local x = {} 
p("ret is a2", rawequal(table.move({1},1,1,1,x), x))
-- nils moved
local h = {1,nil,3}
local hd = {"a","b","c"}
table.move(h,1,3,1,hd)
p("nils", tostring(hd[1]),tostring(hd[2]),tostring(hd[3]), #hd)
EOF
